// app/page.tsx (Server Component)
import ClientInteractiveChart from './ClientChart';

export default async function Page() {
  const data = await getSecureAdminData();

  // 2. Data serialization rule:
  // You CANNOT pass the raw DB response if it contains complex Objects (like Dates).
  // You must map it down to pure serializable JSON strings/numbers first!
  const safeData = data.map(row => ({
    id: row.id,
    dateStr: row.createdAt.toISOString() // Convert Date object to String!
  }));

  return <ClientInteractiveChart data={safeData} />;
}
